-- Profiles: one row per user, created automatically when someone signs up.
-- Added by the `app` kit. Apply it once to YOUR OWN Supabase project: paste this file into
-- Supabase > SQL Editor and click Run, or ask Claude Code to apply it with the Supabase MCP.
-- Do not edit this file after it has been applied: write a new migration instead.

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text check (char_length(display_name) <= 60),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.profiles is 'Public profile for each auth user. Row created by the on_auth_user_created trigger.';

-- Row Level Security: with no policy, nobody can read or write. The policies below let a
-- signed-in user see and change only their own row. Visitors who are not signed in get nothing.
alter table public.profiles enable row level security;

create policy "Users can view their own profile"
  on public.profiles for select
  to authenticated
  using ((select auth.uid()) = id);

create policy "Users can update their own profile"
  on public.profiles for update
  to authenticated
  using ((select auth.uid()) = id)
  with check ((select auth.uid()) = id);

-- Rows are only created by the trigger below and removed with the user, so there is no
-- insert or delete policy. Users may only change display_name (not id or created_at).
revoke insert, update, delete on public.profiles from anon, authenticated;
grant update (display_name) on public.profiles to authenticated;

-- Keep updated_at current.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- Create the profile row when a user signs up. `security definer` lets it write to
-- public.profiles from the auth schema; the empty search_path stops it from running
-- look-alike functions from other schemas.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (
    new.id,
    nullif(
      left(
        trim(
          coalesce(
            new.raw_user_meta_data ->> 'display_name',
            new.raw_user_meta_data ->> 'full_name',
            new.raw_user_meta_data ->> 'name',
            ''
          )
        ),
        60
      ),
      ''
    )
  );
  return new;
end;
$$;

-- Only the trigger should run this, not visitors through the API.
revoke execute on function public.handle_new_user() from public, anon, authenticated;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();
